solution:
class Person:
    def __init__(self, name):
        self.name = name


class Student(Person):
    def __init__(self, name, school):
        super().__init__(name)
        self.school = school


def card(name, school):
    s = Student(name, school)
    return f"{s.name} ({s.school})"

